<template><main class="page"><header><div><p class="eyebrow">STAGE 25 CONTROL PLANE</p><h1>可证明自治与全球连续智能</h1><p>每次高风险自治执行都有证明，每次全球故障都有可接管的最小内核。</p></div><el-button :icon="Refresh" circle title="刷新" :loading="loading" @click="load"/></header><section class="metrics"><div v-for="item in metrics" :key="item.key"><span>{{item.label}}</span><strong>{{overview[item.key]??0}}</strong></div></section><el-tabs v-model="tab"><el-tab-pane label="执行证明" name="proof"><div class="split"><section><h2>编译决策证明</h2><el-form label-position="top"><el-form-item label="行动标识"><el-input v-model="form.action_id"/></el-form-item><el-form-item label="目标"><el-input v-model="form.objective.goal"/></el-form-item><el-checkbox v-model="form.result.approved">结果已审批</el-checkbox><br/><el-button type="primary" :icon="DocumentChecked" @click="compile">编译并验证</el-button></el-form></section><section class="gate"><el-icon><Lock/></el-icon><div><strong>证明先于执行</strong><p>证据、策略、约束或结果签名不匹配时，执行状态保持 blocked。</p></div></section></div></el-tab-pane><el-tab-pane label="全球连续性" name="continuity"><section class="grid"><article v-for="item in capabilities" :key="item.title"><el-icon><component :is="item.icon"/></el-icon><h2>{{item.title}}</h2><p>{{item.text}}</p><el-tag effect="plain" :type="item.type">{{item.state}}</el-tag></article></section></el-tab-pane><el-tab-pane label="经济与责任" name="economy"><section class="grid"><article><el-icon><TrendCharts/></el-icon><h2>预测市场</h2><p>抵押加权概率、集中度反操纵与 Brier 评分结算。</p></article><article><el-icon><Money/></el-icon><h2>责任赔付</h2><p>责任链、仲裁、赔付、追偿和准备金执行会计守恒。</p></article><article><el-icon><Sunny/></el-icon><h2>绿色调度</h2><p>在驻留和 SLA 约束内选择最低碳的可用窗口。</p></article></section></el-tab-pane></el-tabs></main></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{Connection,DocumentChecked,Lock,Money,Refresh,Sunny,TrendCharts,Warning}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import{provableAutonomyApi}from'@/api/provableAutonomy';const loading=ref(false),tab=ref('proof'),overview=reactive<Record<string,number>>({}),form=reactive({action_id:'',objective:{goal:''},constraints:{required_result:{approved:true}},evidence:[{source:'operator'}],policy:{version:'1'},result:{approved:false}});const metrics=computed(()=>[{key:'proofs',label:'决策证明'},{key:'model_checks',label:'模型检查'},{key:'replicas',label:'区域副本'},{key:'quarantined_memories',label:'隔离记忆'},{key:'blocked_collectives',label:'阻断群体'},{key:'markets',label:'预测市场'},{key:'kernel_tests',label:'内核演练'},{key:'settlements',label:'赔付结算'}]),capabilities=[{title:'三区主动运行',text:'向量时钟、确定性冲突收敛和健康区域故障切换。',state:'连续运行',type:'success',icon:Connection},{title:'Agent 群体安全',text:'规模、委托深度、工具、预算和通信的硬限制。',state:'强制门禁',type:'danger',icon:Warning},{title:'灾难最小内核',text:'外部依赖中断时保留身份、策略、审计、告警和人工接管。',state:'可离线',type:'warning',icon:Lock}];async function load(){loading.value=true;try{Object.assign(overview,await provableAutonomyApi.overview())}finally{loading.value=false}}async function compile(){try{const r=await provableAutonomyApi.compileProof(form);ElMessage[r.status==='executable'?'success':'warning'](r.status==='executable'?'证明有效，可执行':'证明未通过，已阻断');await load()}catch{ElMessage.error('决策证明编译失败')}}onMounted(load)</script>
<style scoped>.page{max-width:1220px;margin:auto;padding:28px 24px 48px}.page header{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--el-border-color);padding-bottom:20px}.page h1{font-size:30px;margin:4px 0 6px;letter-spacing:0}.page header p{margin:0;color:var(--el-text-color-secondary)}.eyebrow{font-size:12px!important;color:var(--el-color-primary)!important;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(8,1fr);margin-bottom:22px}.metrics>div{padding:18px 12px;border-bottom:1px solid var(--el-border-color);border-right:1px solid var(--el-border-color)}.metrics span{display:block;font-size:12px;color:var(--el-text-color-secondary)}.metrics strong{font-size:24px}.split{display:grid;grid-template-columns:1fr 1fr;gap:40px;padding:12px 0}.split h2,.grid h2{font-size:17px}.split .gate{display:flex;gap:14px;border-block:1px solid var(--el-border-color);padding:22px 0;align-self:start}.gate .el-icon,.grid .el-icon{font-size:25px;color:var(--el-color-primary)}.gate p,.grid p{color:var(--el-text-color-secondary);line-height:1.6}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--el-border-color);border:1px solid var(--el-border-color)}.grid article{background:var(--el-bg-color);padding:24px;min-height:180px}@media(max-width:800px){.metrics{grid-template-columns:repeat(2,1fr)}.split,.grid{grid-template-columns:1fr}.page{padding:18px 14px}.page h1{font-size:25px}}</style>
